// === Tab: mySketch ===
let simplex
let theta=0
let xNoise, yNoise
let xMove
let yMove
let scaler=1

function setup() {
	createCanvas(windowWidth, windowWidth*.75);
	colorMode(HSB, 255);
	background(0);
	simplex = new OpenSimplexNoise(Date.now());
	xNoise= new noiseLoop(2, 50, 400)
	yNoise= new noiseLoop(3, 50, 400)
	xMove=random(1000)
	yMove=random(1000)
	noFill();

}

function draw() {
	if(scaler>0){
  stroke(frameCount%255, 200, 255)
	//stroke(255)
	push()
	xMove+=0.001
	yMove+=0.001
	xmover= map(simplex.noise2D(xMove, frameCount/1000), -1, 1, -width/3, width/3)
	ymover= map(simplex.noise2D(yMove, frameCount/1000), -1, 1, -height/3, height/3)
	translate(width/2+xmover, height/2+ ymover)
	beginShape()
	scale(scaler)
	for(let i=0; i<=TAU; i+=TAU/100){
		let x= cos(i)*xNoise.value(i)
		let y= sin(i)*yNoise.value(i)
		curveVertex(x, y)
	}
	endShape(CLOSE)
	pop()
scaler-=0.0004
	}
}

class noiseLoop{

	constructor(diameter, min, max){
		this.diameter=diameter
		this.min=min
		this.max=max
	}
	value(theta){
		let xoff=map(cos(theta), -1, 1, 0, this.diameter)
		let yoff=map(sin(theta), -1, 1, 0, this.diameter)
		let r= simplex.noise3D(xoff, yoff, frameCount/100)
		return map(r, -1, 1, this.min, this.max)

	}

}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +      ".jpg");
    lapse = millis();
  }
}

